package alphametics

import (
	"errors"
	"strings"
)

// Solve solves an alphametics puzzle of the form
// "WORD1 + WORD2 + ... + WORDN == RESULT" and returns the digit assigned to
// each letter. Every letter maps to a distinct digit, and the leading letter
// of a multi-digit word must not be zero. An error is returned when the
// puzzle has no valid solution.
func Solve(puzzle string) (map[string]int, error) {
	s := &solver{letterIdx: map[rune]int{}}
	if err := s.parse(puzzle); err != nil {
		return nil, err
	}
	if !s.solve(0, 0) {
		return nil, errors.New("no solution")
	}
	return s.solution(), nil
}

type solver struct {
	addends   []string
	result    string
	letterIdx map[rune]int
	assign    []int  // digit per letter, -1 if unassigned
	leading   []bool // whether a letter may not be zero
	used      [10]bool
	numCols   int
}

// slot is an unassigned letter in the current column, together with the
// number of times it appears in that column.
type slot struct {
	letter int
	count  int
}

func (s *solver) parse(puzzle string) error {
	eq := strings.Split(puzzle, " == ")
	if len(eq) != 2 {
		return errors.New("invalid puzzle: expected exactly one '=='")
	}
	s.addends = strings.Split(eq[0], " + ")
	for _, w := range s.addends {
		if w == "" {
			return errors.New("invalid puzzle: empty addend")
		}
	}
	if fields := strings.Fields(eq[1]); len(fields) != 1 {
		return errors.New("invalid puzzle: expected exactly one result word")
	}
	s.result = fields[0]

	words := append(append([]string{}, s.addends...), s.result)
	for _, w := range words {
		for _, r := range w {
			if _, ok := s.letterIdx[r]; !ok {
				s.letterIdx[r] = len(s.assign)
				s.assign = append(s.assign, -1)
				s.leading = append(s.leading, false)
			}
		}
	}
	if len(s.assign) > 10 {
		return errors.New("invalid puzzle: more than ten distinct letters")
	}
	for _, w := range words {
		if len(w) > 1 {
			s.leading[s.letterIdx[rune(w[0])]] = true
		}
	}
	s.numCols = len(s.result)
	for _, w := range s.addends {
		if len(w) > s.numCols {
			s.numCols = len(w)
		}
	}
	return nil
}

// solve processes the puzzle column by column, from the rightmost column
// (index 0) to the left, carrying the running carry from the previous column.
func (s *solver) solve(col, carry int) bool {
	if col == s.numCols {
		return carry == 0
	}
	sum := 0
	counts := make(map[int]int)
	for _, w := range s.addends {
		if len(w) > col {
			li := s.letterIdx[rune(w[len(w)-1-col])]
			if d := s.assign[li]; d >= 0 {
				sum += d
			} else {
				counts[li]++
			}
		}
	}
	var unassigned []slot
	for li, c := range counts {
		unassigned = append(unassigned, slot{letter: li, count: c})
	}
	resLetter := -1
	if len(s.result) > col {
		resLetter = s.letterIdx[rune(s.result[len(s.result)-1-col])]
	}
	return s.solveCol(col, carry, sum, unassigned, resLetter)
}

// solveCol assigns digits to the unassigned letters of one column such that
// the column sums correctly, then recurses to the next column.
func (s *solver) solveCol(col, carry, sum int, unassigned []slot, resLetter int) bool {
	if len(unassigned) == 0 {
		total := sum + carry
		if resLetter < 0 {
			// The result has no digit in this column, so the column sum
			// (including the carry in) must be exactly zero.
			if total != 0 {
				return false
			}
			return s.solve(col+1, 0)
		}
		if d := s.assign[resLetter]; d >= 0 {
			if d != total%10 {
				return false
			}
			return s.solve(col+1, total/10)
		}
		d := total % 10
		if s.used[d] || (s.leading[resLetter] && d == 0) {
			return false
		}
		s.assign[resLetter] = d
		s.used[d] = true
		if s.solve(col+1, total/10) {
			return true
		}
		s.assign[resLetter] = -1
		s.used[d] = false
		return false
	}
	sl := unassigned[0]
	for d := 0; d <= 9; d++ {
		if s.used[d] || (s.leading[sl.letter] && d == 0) {
			continue
		}
		s.assign[sl.letter] = d
		s.used[d] = true
		if s.solveCol(col, carry, sum+d*sl.count, unassigned[1:], resLetter) {
			return true
		}
		s.assign[sl.letter] = -1
		s.used[d] = false
	}
	return false
}

func (s *solver) solution() map[string]int {
	out := make(map[string]int, len(s.assign))
	for r, li := range s.letterIdx {
		out[string(r)] = s.assign[li]
	}
	return out
}

